import pandas as pd
import numpy as np

def clean_value(v):
    if pd.isna(v):
        return np.nan
    if isinstance(v, str):
        v = v.replace(',', '.')
    try:
        return float(v)
    except:
        return np.nan

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')
for col in df.columns:
    if col != 'patient_id':
        df[col] = df[col].apply(clean_value)

stats = df.describe(percentiles=[0.01, 0.05, 0.25, 0.5, 0.75, 0.95, 0.99]).transpose()
stats.to_csv('/root/data_stats.csv')
print(stats[['min', '1%', '5%', '50%', '95%', '99%', 'max']])
